const list = <T,>(path: string) => api<{ data: T[] }>(path);
const uncertainOrderKey = (hostId: string) => `skybar-uncertain-order:${hostId}`;

function loadUncertainOrder(hostId: string): QueuedMutation | null {
  try {
    const durable=localStorage.getItem(uncertainOrderKey(hostId));
    const legacy=sessionStorage.getItem(uncertainOrderKey(hostId));
    if(legacy)sessionStorage.removeItem(uncertainOrderKey(hostId));
    if(!durable&&legacy)localStorage.setItem(uncertainOrderKey(hostId),legacy);
    const raw = durable??legacy;
    if (!raw) return null;
    const mutation = JSON.parse(raw) as QueuedMutation;
    if (mutation.hostId === hostId && mutation.path === '/order-batches' && mutation.display?.kind === 'order') return mutation;
  } catch { /* Ignore and remove malformed recovery state below. */ }
  localStorage.removeItem(uncertainOrderKey(hostId));sessionStorage.removeItem(uncertainOrderKey(hostId));
  return null;
}

function persistUncertainOrder(hostId: string, mutation: QueuedMutation | null): void {
  sessionStorage.removeItem(uncertainOrderKey(hostId));
  if (mutation) localStorage.setItem(uncertainOrderKey(hostId), JSON.stringify(mutation));
  else localStorage.removeItem(uncertainOrderKey(hostId));
}

export function DashboardPage() {
  const { t, language } = useI18n();
  const { venue } = useHostContext();
  const stats = useQuery<{ pendingRequests:number;activeRooms:number;activeGuests:number;openItemCount:number;openValueCents:number;todaySalesCents:number }>({ queryKey:['dashboard'], queryFn:()=>api('/dashboard') });
  const orders = useQuery<{data:TabSummary[]}>({queryKey:['orders'],queryFn:()=>list('/orders')});
  const cards = [
    {label:t('requests'),value:stats.data?.pendingRequests ?? '–',icon:Clock3,tone:'violet'},
    {label:t('guests'),value:stats.data?.activeGuests ?? '–',icon:Users,tone:'blue'},
    {label:t('orders'),value:formatMoney(stats.data?.openValueCents ?? 0,language),detail:`${stats.data?.openItemCount ?? 0} ${t('items')}`,icon:GlassWater,tone:'amber'},
    {label:t('today'),value:formatMoney(stats.data?.todaySalesCents ?? 0,language),icon:CircleDollarSign,tone:'green'},
  ];
  return <><PageHeader eyebrow={venue.name} title={`${t('welcome')}, ${venue.name}`} actions={<a className="button button--primary" href="/app/orders/new"><GlassWater/> {t('takeOrders')}</a>}/><div className="metric-grid">{cards.map(({icon:Icon,...card})=><Card key={card.label} className={`metric metric--${card.tone}`}><Icon/><span>{card.label}</span><strong>{card.value}</strong>{card.detail&&<small>{card.detail}</small>}</Card>)}</div><div className="section-heading"><h2>{t('orders')}</h2><a href="/app/orders">{t('viewAll')} <ChevronRight/></a></div><Card>{orders.data?.data.length?<div className="table-list">{orders.data.data.slice(0,6).map(order=><a className="table-row" href={`/app/orders/new?guest=${order.guestId}`} key={order.id}><div className="avatar">{order.guestName.charAt(0)}</div><div className="grow"><strong>{order.guestName}</strong><span>{order.roomName} · {order.itemCount} {t('items')}</span></div><strong>{formatMoney(order.totalCents,language)}</strong><ChevronRight/></a>)}</div>:<Empty>{t('empty')}</Empty>}</Card></>;
}

export function TakeOrdersPage() {
  const { t, language } = useI18n();
  const { host } = useHostContext();
  const client = useQueryClient();
  const [,navigate] = useLocation();
  const rooms = useQuery<{data:Room[]}>({queryKey:['rooms'],queryFn:()=>list('/rooms')});
  const guests = useQuery<{data:Guest[]}>({queryKey:['guests'],queryFn:()=>list('/guests')});
  const categories = useQuery<{data:Category[]}>({queryKey:['categories'],queryFn:()=>list('/categories')});
  const products = useQuery<{data:Product[];catalogVersion:number}>({queryKey:['products'],queryFn:()=>api('/products')});
  const [restoredSubmission]=useState(()=>loadUncertainOrder(host.id));
  const initialGuest = restoredSubmission?.display?.kind === 'order'
    ? restoredSubmission.display.guestId
    : new URLSearchParams(location.search).get('guest') ?? '';
  const initialGuestData = guests.data?.data.find((guest)=>guest.id===initialGuest);
  const [roomId,setRoomId]=useState(initialGuestData?.roomId ?? '');
  const [guestId,setGuestId]=useState(initialGuest);
  const [search,setSearch]=useState('');
  const [cart,setCart]=useState<Record<string,number>>(()=>restoredSubmission?.display?.kind === 'order'
    ? Object.fromEntries(restoredSubmission.display.items.map(item=>[item.productId,item.quantity]))
    : {});
  const [createGuest,setCreateGuest]=useState(false);
  const [settleTab,setSettleTab]=useState<Tab|null>(null);
  const [voidingItem,setVoidingItem]=useState<{item:OrderItem;mutationId:string;createdAt:string}|null>(null);
  const [submitting,setSubmitting]=useState(false);
  const [uncertainOrder,setUncertainOrder]=useState(Boolean(restoredSubmission));
  const [message,setMessage]=useState<{kind:'success'|'error';text:string}|null>(()=>restoredSubmission?{kind:'error',text:t('uncertainOrderHelp')}:null);
  const stagedSubmission=useRef<QueuedMutation|null>(restoredSubmission);
  const tab=useQuery<Tab>({queryKey:['tab',guestId],queryFn:async()=>{const current=await api<Tab>(`/guests/${guestId}/tab`);return current.itemCount>0?current:{...current,id:null}},enabled:Boolean(guestId)});
  const selectedGuest=guests.data?.data.find(guest=>guest.id===guestId);
  const eligibleProducts=products.data?.data.filter(product=>product.enabled&&!product.selfServiceOnly)??[];
  const stagedDisplay=stagedSubmission.current?.display?.kind==='order'?stagedSubmission.current.display:undefined;
  const cartLines=stagedDisplay
    ? stagedDisplay.items.map(item=>({product:{id:item.productId,name:item.productName,priceCents:item.unitPriceCents??products.data?.data.find(product=>product.id===item.productId)?.priceCents??0},quantity:item.quantity}))
    : Object.entries(cart).flatMap(([productId,quantity])=>{const product=products.data?.data.find(item=>item.id===productId);return product?[{product,quantity}]:[]});
  const cartTotal=cartLines.reduce((sum,line)=>sum+line.product.priceCents*line.quantity,0);
  useEffect(()=>{const selected=guests.data?.data.find(guest=>guest.id===guestId);if(selected&&!roomId)setRoomId(selected.roomId)},[guestId,guests.data?.data,roomId]);
  const selectGuest=(nextGuestId:string,nextRoomId:string)=>{
    if(nextGuestId!==guestId&&uncertainOrder){setMessage({kind:'error',text:t('uncertainOrderHelp')});return}
    if(nextGuestId!==guestId&&cartLines.length){
      if(!globalThis.confirm(t('changeGuestCartWarning')))return;
      setCart({});stagedSubmission.current=null;persistUncertainOrder(host.id,null);
    }
    setGuestId(nextGuestId);setRoomId(nextRoomId);
  };
  const add=(productId:string,change:number)=>{if(!uncertainOrder&&!submitting)setCart(current=>updateOrderCart(current,productId,change))};
  const submit=async()=>{
    if(!guestId||!products.data||(!stagedSubmission.current&&!cartLines.length))return;
    setSubmitting(true);
    if(!stagedSubmission.current){
      const mutationId=crypto.randomUUID();const capturedAt=new Date().toISOString();const items=cartLines.map(line=>({productId:line.product.id,quantity:line.quantity}));
      stagedSubmission.current={id:mutationId,hostId:host.id,path:'/order-batches',method:'POST',createdAt:capturedAt,body:{mutationId,originHostId:host.id,guestId,catalogVersion:products.data.catalogVersion,capturedAt,items},display:{kind:'order',guestId,guestName:selectedGuest?.name??guestId,roomName:selectedGuest?.roomName??'',items:cartLines.map(line=>({productId:line.product.id,productName:line.product.name,unitPriceCents:line.product.priceCents,quantity:line.quantity}))}};
      try { persistUncertainOrder(host.id,stagedSubmission.current); }
      catch { stagedSubmission.current=null;setSubmitting(false);setMessage({kind:'error',text:t('requestFailed')});return; }
    }
    try{const result=await submitOrQueue(stagedSubmission.current);persistUncertainOrder(host.id,null);stagedSubmission.current=null;setUncertainOrder(false);setCart({});setMessage({kind:'success',text:result.queued?t('orderQueued'):t('orderAdded')});await client.invalidateQueries({queryKey:['tab',guestId]});}
    catch(caught){const uncertain=!(caught instanceof ApiError)||caught.status===408||caught.status>=500;setUncertainOrder(uncertain);if(!uncertain){persistUncertainOrder(host.id,null);stagedSubmission.current=null}setMessage({kind:'error',text:uncertain?t('uncertainOrderHelp'):apiErrorMessage(caught,language,t('requestFailed'))});}
    finally{setSubmitting(false)}
  };
  const voidItem=async(reason:string)=>{
    if(!voidingItem||!guestId)return;
    const result=await submitOrQueue({id:voidingItem.mutationId,hostId:host.id,path:`/order-items/${voidingItem.item.id}/void`,method:'POST',createdAt:voidingItem.createdAt,body:{mutationId:voidingItem.mutationId,reason},display:{kind:'void',guestId,guestName:selectedGuest?.name??guestId,roomName:selectedGuest?.roomName??'',productName:voidingItem.item.productName,quantity:voidingItem.item.quantity}});
    setVoidingItem(null);
    setMessage({kind:'success',text:result.queued?t('itemVoidQueued'):t('itemVoided')});
    if(!result.queued)await Promise.all([client.invalidateQueries({queryKey:['tab',guestId]}),client.invalidateQueries({queryKey:['orders']}),client.invalidateQueries({queryKey:['guests']})]);
  };
  const visibleGuests=(guests.data?.data??[]).filter(guest=>(!roomId||guest.roomId===roomId)&&(!search||`${guest.name} ${guest.roomName}`.toLowerCase().includes(search.toLowerCase())));
  return <><PageHeader eyebrow={t('takeOrders')} title={selectedGuest?selectedGuest.name:t('selectGuest')} actions={selectedGuest&&<div className="tab-pill"><span>{tab.data?.itemCount??0} {t('items')}</span><strong>{formatMoney(tab.data?.totalCents??0,language)}</strong></div>}/>{message&&<Notice kind={message.kind}>{message.text}</Notice>}<div className="order-workspace"><aside className="guest-picker"><div className="room-chips">{rooms.data?.data.map(room=><button className={room.id===roomId?'active':''} key={room.id} onClick={()=>selectGuest('',room.id)} disabled={submitting||uncertainOrder}>{room.name}</button>)}</div><label className="search"><Search/><input aria-label={t('searchGuests')} value={search} onChange={e=>setSearch(e.target.value)} placeholder={t('searchGuests')}/></label><div className="guest-list">{visibleGuests.map(guest=><button className={guest.id===guestId?'active':''} onClick={()=>selectGuest(guest.id,guest.roomId)} key={guest.id} disabled={submitting||uncertainOrder}><span className="avatar">{guest.name.charAt(0)}</span><span><strong>{guest.name}</strong><small>{guest.roomName} · {formatMoney(guest.totalCents,language)}</small></span><ChevronRight/></button>)}</div><Button variant="secondary" onClick={()=>setCreateGuest(true)} disabled={!navigator.onLine||submitting||uncertainOrder}><UserPlus/> {t('add')} {t('guests')}</Button></aside><section className="catalog"><div className="catalog-toolbar"><h2>{t('products')}</h2><span>{cartLines.reduce((sum,line)=>sum+line.quantity,0)} {t('selected')}</span></div>{categories.data?.data.map(category=>{const categoryProducts=eligibleProducts.filter(product=>product.categoryId===category.id);if(!categoryProducts.length)return null;return <div className="catalog-group" key={category.id}><h3>{localized(category.name,language)}</h3><div className="product-grid">{categoryProducts.map(product=><button className={`product-tile ${cart[product.id]?'selected':''}`} key={product.id} onClick={()=>add(product.id,1)} disabled={!guestId||submitting||uncertainOrder||!canAddOrderProduct(cart,product.id)}><span>{localized(product.name,language)}</span><strong>{formatMoney(product.priceCents,language)}</strong>{cart[product.id]&&<b>{cart[product.id]}</b>}<Plus/></button>)}</div></div>})}</section><aside className="cart-panel"><h2>{t('orders')}</h2>{cartLines.length?<div className="cart-lines">{cartLines.map(({product,quantity})=><div key={product.id}><div><strong>{localized(product.name,language)}</strong><span>{formatMoney(product.priceCents*quantity,language)}</span></div><div className="stepper"><button onClick={()=>add(product.id,-1)} disabled={submitting||uncertainOrder}><Minus/></button><b>{quantity}</b><button onClick={()=>add(product.id,1)} disabled={submitting||uncertainOrder||!canAddOrderProduct(cart,product.id)}><Plus/></button></div></div>)}</div>:<Empty>{t('selectProducts')}</Empty>}<div className="cart-total"><span>{t('total')}</span><strong>{formatMoney(cartTotal,language)}</strong></div><Button onClick={()=>void submit()} disabled={submitting||!guestId||(!cartLines.length&&!stagedSubmission.current)}><Check/> {submitting?'…':uncertainOrder?t('retry'):t('submitOrder')}</Button>{Boolean(tab.data?.items.length)&&<div className="open-tab"><h3>{t('currentTab')}</h3>{tab.data!.items.map(item=><div key={item.id}><div><strong>{item.quantity} × {localized(item.productName,language)}</strong><span>{formatMoney(item.unitPriceCents*item.quantity,language)}</span></div><Button variant="ghost" aria-label={`${t('voidItem')} ${localized(item.productName,language)}`} onClick={()=>setVoidingItem({item,mutationId:crypto.randomUUID(),createdAt:new Date().toISOString()})}><Trash2/></Button></div>)}</div>}{tab.data?.id&&<Button variant="secondary" onClick={()=>setSettleTab(tab.data!)} disabled={!navigator.onLine}><CreditCard/> {t('settle')} · {formatMoney(tab.data.totalCents,language)}</Button>}</aside></div>{createGuest&&<NewGuestModal rooms={rooms.data?.data??[]} initialRoom={roomId} onClose={()=>setCreateGuest(false)} onCreated={async guest=>{await client.invalidateQueries({queryKey:['guests']});selectGuest(guest.id,guest.roomId);setCreateGuest(false)}}/>}{settleTab&&<SettleModal tab={settleTab} onClose={()=>setSettleTab(null)} onSettled={(billId)=>navigate(`/app/bills/${billId}`)}/>} {voidingItem&&<Modal title={`${t('voidItem')} · ${localized(voidingItem.item.productName,language)}`} onClose={()=>setVoidingItem(null)}><ConfirmForm label={t('reason')} placeholder={t('voidItem')} onCancel={()=>setVoidingItem(null)} onConfirm={voidItem} onDefinitiveFailure={()=>setVoidingItem(current=>current?{...current,mutationId:crypto.randomUUID(),createdAt:new Date().toISOString()}:current)}/></Modal>}</>;
}

function NewGuestModal({rooms,initialRoom,onClose,onCreated}:{rooms:Room[];initialRoom:string;onClose:()=>void;onCreated:(guest:{id:string;roomId:string})=>void}){
  const {t,language}=useI18n();const [name,setName]=useState('');const [roomId,setRoomId]=useState(initialRoom);const [error,setError]=useState('');const [pendingCommand,setPendingCommand]=useState<{mutationId:string;name:string;roomId:string;language:Language}>();
  const submit=async(event:FormEvent)=>{event.preventDefault();const command=pendingCommand??{mutationId:crypto.randomUUID(),name:name.trim(),roomId,language};setPendingCommand(command);try{const guest=await api<{id:string;roomId:string}>('/guests',{method:'POST',body:json(command)});onCreated(guest)}catch(caught){if(isPermanentSyncConflict(caught))setPendingCommand(undefined);setError(apiErrorMessage(caught,language,t('requestFailed')))}};
  return <Modal title={`${t('add')} ${t('guests')}`} onClose={onClose}><form className="stack" onSubmit={submit}><Field label={t('name')}><input value={name} onChange={e=>setName(e.target.value)} required autoFocus disabled={Boolean(pendingCommand)}/></Field><Field label={t('rooms')}><select value={roomId} onChange={e=>setRoomId(e.target.value)} required disabled={Boolean(pendingCommand)}><option value="">{t('selectRoom')}</option>{rooms.map(room=><option key={room.id} value={room.id}>{room.name}</option>)}</select></Field>{error&&<Notice kind="error">{error}</Notice>}<div className="form-actions"><Button variant="ghost" type="button" onClick={onClose}>{t('cancel')}</Button><Button type="submit">{pendingCommand?t('retry'):t('save')}</Button></div></form></Modal>;
}

function SettleModal({tab,onClose,onSettled}:{tab:Tab;onClose:()=>void;onSettled:(billId:string)=>void}){
  const {t,language}=useI18n();const [snapshot,setSnapshot]=useState(tab);const [method,setMethod]=useState<'cash'|'card'|'other'>('cash');const [note,setNote]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [mutationId,setMutationId]=useState(()=>crypto.randomUUID());const [command,setCommand]=useState<{paymentMethod:'cash'|'card'|'other';note?:string}|null>(null);
  const submit=async(event:FormEvent)=>{event.preventDefault();setBusy(true);const frozen=command??{paymentMethod:method,...(note?{note}: {})};setCommand(frozen);try{const bill=await api<{id:string}>(`/tabs/${snapshot.id}/settle`,{method:'POST',body:json({mutationId,expectedItemCount:snapshot.itemCount,expectedTotalCents:snapshot.totalCents,...frozen})});onSettled(bill.id)}catch(caught){if(caught instanceof ApiError&&caught.code==='EMPTY_TAB'){onClose();return}if(caught instanceof ApiError&&caught.code==='TAB_CHANGED'){try{const refreshed=await api<Tab>(`/guests/${snapshot.guestId}/tab`);if(!refreshed.id||refreshed.itemCount===0){onClose();return}setSnapshot(refreshed);setMutationId(crypto.randomUUID())}catch{onClose();return}}if(isPermanentSyncConflict(caught))setCommand(null);setError(apiErrorMessage(caught,language,t('requestFailed')));setBusy(false)}};
  return <Modal title={t('settle')} onClose={onClose}><form className="stack" onSubmit={submit}><div className="settle-total"><span>{snapshot.itemCount} {t('items')}</span><strong>{formatMoney(snapshot.totalCents,language)}</strong></div><div className="choice-grid">{(['cash','card','other'] as const).map(value=><button type="button" className={method===value?'active':''} key={value} onClick={()=>setMethod(value)} disabled={busy||Boolean(command)}>{value==='cash'?<Euro/>:<CreditCard/>}<span>{t(value)}</span></button>)}</div>{method==='other'&&<Field label={t('note')}><input value={note} onChange={e=>setNote(e.target.value)} maxLength={240} disabled={busy||Boolean(command)}/></Field>}{error&&<Notice kind="error">{error}</Notice>}<Button type="submit" disabled={busy}>{busy?'…':command?t('retry'):t('settle')}</Button></form></Modal>;
}

export function OrdersPage(){
  const {t,language}=useI18n();const orders=useQuery<{data:TabSummary[]}>({queryKey:['orders'],queryFn:()=>list('/orders')});
  return <><PageHeader eyebrow={t('live')} title={t('orders')} actions={<a className="button button--primary" href="/app/orders/new"><Plus/> {t('takeOrders')}</a>}/><div className="card-grid">{orders.data?.data.map(order=><Card key={order.id} className="tab-card"><div className="avatar large">{order.guestName.charAt(0)}</div><div className="grow"><h2>{order.guestName}</h2><p><BedDouble/> {order.roomName}</p><span>{order.itemCount} {t('items')}</span></div><strong>{formatMoney(order.totalCents,language)}</strong><a className="button button--secondary" href={`/app/orders/new?guest=${order.guestId}`}>{t('edit')} <ChevronRight/></a></Card>)}</div>{!orders.data?.data.length&&<Card><Empty>{t('empty')}</Empty></Card>}</>;
}

interface BillsResult { data: Bill[]; pagination: { page: number; pageSize: number; total: number; totalPages: number } }
export function BillsPage(){
  const {t,language}=useI18n();
  const [search,setSearch]=useState('');
  const [page,setPage]=useState(1);
  const bills=useQuery<BillsResult>({
    queryKey:['bills',search,page],
    queryFn:()=>api(`/bills?search=${encodeURIComponent(search)}&page=${page}&pageSize=50`),
  });
  const visible=bills.data?.data??[];
  const pagination=bills.data?.pagination;
  return <><PageHeader eyebrow={t('archive')} title={t('bills')}/><label className="search wide"><Search/><input value={search} onChange={e=>{setSearch(e.target.value);setPage(1)}} placeholder={t('searchBills')}/></label><Card>{visible.length?<div className="table-list bills-list">{visible.map(bill=><a className={`table-row ${bill.voidedAt?'voided':''}`} href={`/app/bills/${bill.id}`} key={bill.id}><div className="receipt-number"><Receipt/>#{bill.number}</div><div className="grow"><strong>{bill.guestName}</strong><span>{bill.roomName} · {formatVenueDateTime(bill.settledAt,language,bill.venueTimezone)}</span></div><span className="payment-tag">{t(bill.paymentMethod as 'cash'|'card'|'other')}</span><strong>{formatMoney(bill.totalCents,language)}</strong><ChevronRight/></a>)}</div>:<Empty>{t('empty')}</Empty>}</Card>{pagination&&pagination.totalPages>1&&<nav className="pagination" aria-label={t('bills')}><Button variant="secondary" disabled={page<=1} onClick={()=>setPage(current=>Math.max(1,current-1))}><ChevronLeft/>{t('previous')}</Button><span>{t('page')} {pagination.page} / {pagination.totalPages}</span><Button variant="secondary" disabled={page>=pagination.totalPages} onClick={()=>setPage(current=>current+1)}>{t('next')}<ChevronRight/></Button></nav>}</>;
}

interface BillDetail extends Bill { paymentNote?:string;voidReason?:string;hostName:string;hostNameKnown:boolean;items:{productName:LocalizedText;unitPriceCents:number;quantity:number;source:string}[] }
export function BillDetailPage(){
  const [,params]=useRoute('/app/bills/:id');const billId=params?.id;const {t,language}=useI18n();const {host}=useHostContext();const client=useQueryClient();const bill=useQuery<BillDetail>({queryKey:['bill',billId],queryFn:()=>api(`/bills/${billId}`),enabled:Boolean(billId)});const [voiding,setVoiding]=useState(false);const voidMutationId=useRef(crypto.randomUUID());
  if(!bill.data)return <div className="splash">{t('loading')}</div>;
  return <><PageHeader eyebrow={`${t('bills')} · #${bill.data.number}`} title={bill.data.venueName} actions={<><Button variant="secondary" onClick={()=>window.print()}><Printer/> {t('print')}</Button>{host.role==='admin'&&!bill.data.voidedAt&&<Button variant="danger" onClick={()=>setVoiding(true)}><Trash2/> {t('voidBill')}</Button>}</>}/><article className="bill-sheet"><header><div><img src="/sky-bar.svg" alt=""/><span>{t('poweredBy')}</span></div><h1>{bill.data.venueName}</h1><p>{t('bill')} #{bill.data.number}</p></header>{bill.data.voidedAt&&<div className="bill-void-marker"><Notice kind="error">{t('voided')} · {bill.data.voidReason}</Notice></div>}<div className="bill-meta"><div><span>{t('guest')}</span><strong>{bill.data.guestName}</strong></div><div><span>{t('rooms')}</span><strong>{bill.data.roomName}</strong></div><div><span>{t('date')}</span><strong>{formatVenueDateTime(bill.data.settledAt,language,bill.data.venueTimezone)}</strong></div><div><span>{t('host')}</span><strong>{bill.data.hostNameKnown?bill.data.hostName:t('unknownHost')}</strong></div></div><div className="bill-lines">{bill.data.items.map((item,index)=><div key={index}><span>{item.quantity} × {localized(item.productName,language)}{item.source==='guest'&&<small>{t('selfService')}</small>}</span><span>{formatMoney(item.unitPriceCents*item.quantity,language)}</span></div>)}</div><footer><div><span>{t('total')}</span><strong>{formatMoney(bill.data.totalCents,language)}</strong></div><p>{t(bill.data.paymentMethod as 'cash'|'card'|'other')}{bill.data.paymentNote&&` · ${bill.data.paymentNote}`}</p></footer></article>{voiding&&<Modal title={t('voidBill')} onClose={()=>setVoiding(false)}><ConfirmForm label={t('reason')} placeholder={t('reversalReason')} onCancel={()=>setVoiding(false)} onDefinitiveFailure={()=>{voidMutationId.current=crypto.randomUUID()}} onConfirm={async reason=>{await api(`/bills/${billId}/void`,{method:'POST',body:json({mutationId:voidMutationId.current,reason})});setVoiding(false);await client.invalidateQueries({queryKey:['bill',billId]})}}/></Modal>}</>;
}

