function GuestEditor({guest,rooms,onClose,onSaved}:{guest:Guest|undefined;rooms:Room[];onClose:()=>void;onSaved:()=>void}){const {t,language:uiLanguage}=useI18n();const [name,setName]=useState(guest?.name??'');const [roomId,setRoomId]=useState(guest?.roomId??'');const [language,setLanguage]=useState<Language>(guest?.language??'de');const [error,setError]=useState('');const [pendingCommand,setPendingCommand]=useState<{mutationId:string;name:string;roomId:string;language:Language}>();const locked=!guest&&Boolean(pendingCommand);const submit=async(e:FormEvent)=>{e.preventDefault();const command=guest?{name:name.trim(),roomId,language,expectedVersion:guest.version}:pendingCommand??{mutationId:crypto.randomUUID(),name:name.trim(),roomId,language};if(!guest)setPendingCommand(command as typeof pendingCommand);try{await api(guest?`/guests/${guest.id}`:'/guests',{method:guest?'PATCH':'POST',body:json(command)});onSaved()}catch(caught){if(!guest&&isPermanentSyncConflict(caught))setPendingCommand(undefined);setError(apiErrorMessage(caught,uiLanguage,t('requestFailed')))}};return <Modal title={`${guest?t('edit'):t('add')} ${t('guests')}`} onClose={onClose}><form className="stack" onSubmit={submit}><Field label={t('name')}><input value={name} onChange={e=>setName(e.target.value)} required autoFocus disabled={locked}/></Field><Field label={t('rooms')}><select value={roomId} onChange={e=>setRoomId(e.target.value)} required disabled={locked}><option value="">{t('selectRoom')}</option>{rooms.map(room=><option key={room.id} value={room.id}>{room.name}</option>)}</select></Field><Field label={t('language')}><select value={language} onChange={e=>setLanguage(e.target.value as Language)} disabled={locked}><option value="de">Deutsch</option><option value="it">Italiano</option><option value="en">English</option></select></Field>{error&&<Notice kind="error">{error}</Notice>}<div className="form-actions"><Button variant="ghost" type="button" onClick={onClose}>{t('cancel')}</Button><Button type="submit">{locked?t('retry'):t('save')}</Button></div></form></Modal>}

export function RoomsPage(){
  const {t,language}=useI18n();
  const {host}=useHostContext();
  const client=useQueryClient();
  const rooms=useQuery<{data:Room[]}>({queryKey:['rooms'],queryFn:()=>list('/rooms'),enabled:host.role==='admin'});
  const [name,setName]=useState('');
  const [editing,setEditing]=useState<Room|undefined>();
  const [createError,setCreateError]=useState('');
  const [archiveError,setArchiveError]=useState('');
  const [editError,setEditError]=useState('');
  const [createCommand,setCreateCommand]=useState<{name:string;mutationId:string}>();
  const [reorderError,setReorderError]=useState('');
  const save=async(e:FormEvent)=>{
    e.preventDefault();
    const normalizedName=name.trim();
    const command=createCommand??{name:normalizedName,mutationId:crypto.randomUUID()};
    setCreateCommand(command);
    setCreateError('');
    try{
      await api('/rooms',{method:'POST',body:json(command)});
      setCreateCommand(undefined);setName('');await client.invalidateQueries({queryKey:['rooms']});
    }catch(caught){if(isPermanentSyncConflict(caught))setCreateCommand(undefined);setCreateError(apiErrorMessage(caught,language,t('requestFailed')))}
  };
  const move=async(index:number,direction:number)=>{const ordered=[...rooms.data!.data];const target=index+direction;[ordered[index],ordered[target]]=[ordered[target]!,ordered[index]!];setReorderError('');try{await api('/rooms/order',{method:'PUT',body:json({rooms:ordered.map(room=>({id:room.id,expectedVersion:room.version}))})})}catch(caught){setReorderError(apiErrorMessage(caught,language,t('requestFailed')))}finally{await client.invalidateQueries({queryKey:['rooms']})}};
  const archive=async(roomId:string)=>{setArchiveError('');try{await api(`/rooms/${roomId}`,{method:'DELETE'});await client.invalidateQueries({queryKey:['rooms']})}catch(caught){setArchiveError(apiErrorMessage(caught,language,t('requestFailed')))}};
  const rename=async(e:FormEvent)=>{e.preventDefault();if(!editing)return;setEditError('');try{await api(`/rooms/${editing.id}`,{method:'PATCH',body:json({name:editing.name,expectedVersion:editing.version})});setEditing(undefined);await client.invalidateQueries({queryKey:['rooms']})}catch(caught){setEditError(apiErrorMessage(caught,language,t('requestFailed')))}};
  if(host.role!=='admin')return <Card><Notice kind="error">{t('permissionRequired')}</Notice></Card>;
  return <><PageHeader eyebrow={t('configuration')} title={t('rooms')}/>{archiveError&&<Notice kind="error">{archiveError}</Notice>}{reorderError&&<Notice kind="error">{reorderError}</Notice>}<div className="two-column"><Card><h2>{t('add')} {t('rooms')}</h2><form className="inline-form" onSubmit={save}><input value={name} onChange={e=>setName(e.target.value)} required placeholder={t('roomName')} disabled={Boolean(createCommand)}/><Button type="submit"><Plus/> {createCommand?t('retry'):t('add')}</Button></form>{createError&&<Notice kind="error">{createError}</Notice>}</Card><Card><h2>{t('displayOrder')}</h2><div className="sortable-list">{rooms.data?.data.map((room,index)=><div key={room.id}><span className="drag-index">{String(index+1).padStart(2,'0')}</span><div className="grow"><strong>{room.name}</strong><small>{room.guestCount??0} {t('guests')}</small></div><Button variant="ghost" disabled={index===0} onClick={()=>void move(index,-1)}><ArrowUp/></Button><Button variant="ghost" disabled={index===rooms.data!.data.length-1} onClick={()=>void move(index,1)}><ArrowDown/></Button><Button variant="ghost" onClick={()=>{setEditError('');setEditing(room)}}><Edit3/></Button><Button variant="ghost" aria-label={`${t('archive')} ${room.name}`} onClick={()=>void archive(room.id)}><Trash2/></Button></div>)}</div></Card></div>{editing&&<Modal title={`${t('edit')} ${editing.name}`} onClose={()=>setEditing(undefined)}><form className="stack" onSubmit={rename}><Field label={t('name')}><input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} required maxLength={80} autoFocus/></Field>{editError&&<Notice kind="error">{editError}</Notice>}<Button type="submit">{t('save')}</Button></form></Modal>}</>;
}

export function ProductsPage(){
  const {t,language}=useI18n();const {host}=useHostContext();const client=useQueryClient();const products=useQuery<{data:Product[];catalogVersion:number}>({queryKey:['products'],queryFn:()=>api('/products'),enabled:host.role==='admin'});const categories=useQuery<{data:Category[]}>({queryKey:['categories'],queryFn:()=>list('/categories'),enabled:host.role==='admin'});const [editing,setEditing]=useState<Product|undefined>();const [creating,setCreating]=useState(false);const [categoryName,setCategoryName]=useState('');const [categoryError,setCategoryError]=useState('');const [categoryCommand,setCategoryCommand]=useState<{name:string;mutationId:string}>();
  const addCategory=async(e:FormEvent)=>{e.preventDefault();const normalizedName=categoryName.trim();const command=categoryCommand??{name:normalizedName,mutationId:crypto.randomUUID()};setCategoryCommand(command);setCategoryError('');try{await api('/categories',{method:'POST',body:json({mutationId:command.mutationId,name:{de:command.name,it:'',en:''}})});setCategoryCommand(undefined);setCategoryName('');await client.invalidateQueries({queryKey:['categories']})}catch(caught){if(isPermanentSyncConflict(caught))setCategoryCommand(undefined);setCategoryError(apiErrorMessage(caught,language,t('requestFailed')))}};
  if(host.role!=='admin')return <Card><Notice kind="error">{t('permissionRequired')}</Notice></Card>;
  return <><PageHeader eyebrow={t('catalog')} title={t('products')} actions={<Button onClick={()=>setCreating(true)} disabled={!categories.data?.data.length}><Plus/> {t('add')}</Button>}/><div className="two-column catalog-admin"><Card><h2>{t('categories')}</h2><form className="inline-form" onSubmit={addCategory}><input value={categoryName} onChange={e=>setCategoryName(e.target.value)} placeholder={t('germanName')} required disabled={Boolean(categoryCommand)}/><Button type="submit">{categoryCommand?t('retry'):<Plus/>}</Button></form>{categoryError&&<Notice kind="error">{categoryError}</Notice>}<div className="category-list">{categories.data?.data.map(category=><div key={category.id}><strong>{localized(category.name,language)}</strong><span>{products.data?.data.filter(product=>product.categoryId===category.id).length??0}</span></div>)}</div></Card><Card><div className="product-admin-list">{products.data?.data.map(product=><button key={product.id} onClick={()=>setEditing(product)}><div className="product-mark"><GlassWater/></div><div className="grow"><strong>{localized(product.name,language)}</strong><span>{categories.data?.data.find(category=>category.id===product.categoryId)?localized(categories.data!.data.find(category=>category.id===product.categoryId)!.name,language):'—'} · {product.selfServiceOnly?t('selfService'):t('host')}</span></div><span className={`status-dot ${product.enabled?'enabled':''}`}>{product.enabled?t('enabled'):t('disabled')}</span><strong>{formatMoney(product.priceCents,language)}</strong><Edit3/></button>)}</div>{!products.data?.data.length&&<Empty>{t('empty')}</Empty>}</Card></div>{(creating||editing)&&<ProductEditor product={editing} categories={categories.data?.data??[]} onClose={()=>{setCreating(false);setEditing(undefined)}} onSaved={async()=>{setCreating(false);setEditing(undefined);await client.invalidateQueries({queryKey:['products']})}} onRemove={editing?async()=>{await api(`/products/${editing.id}`,{method:'DELETE'});setEditing(undefined);await client.invalidateQueries({queryKey:['products']})}:undefined}/>}</>;
}

function emptyText():LocalizedText{return {de:'',it:'',en:''}}
interface ProductCreateCommand{mutationId:string;name:LocalizedText;description?:LocalizedText;priceCents:number;categoryId:string;enabled:boolean;selfServiceOnly:boolean}
function ProductEditor({product,categories,onClose,onSaved,onRemove}:{product:Product|undefined;categories:Category[];onClose:()=>void;onSaved:()=>void;onRemove:(()=>void)|undefined}){
  const {t,language}=useI18n();const [name,setName]=useState<LocalizedText>(product?.name??emptyText());const [description,setDescription]=useState<LocalizedText>(product?.description??emptyText());const [price,setPrice]=useState(product?(product.priceCents/100).toFixed(2):'');const [categoryId,setCategoryId]=useState(product?.categoryId??categories[0]?.id??'');const [enabled,setEnabled]=useState(product?.enabled??true);const [selfServiceOnly,setSelfServiceOnly]=useState(product?.selfServiceOnly??false);const [error,setError]=useState('');const [pendingCreate,setPendingCreate]=useState<ProductCreateCommand>();const locked=!product&&Boolean(pendingCreate);const submit=async(e:FormEvent)=>{e.preventDefault();const priceCents=parseEuroCents(price);if(priceCents===undefined){setError(t('invalidPrice'));return}const hasDescription=Object.values(description).some(value=>value.trim().length>0);const productInput={name,description:hasDescription?description:undefined,priceCents,categoryId,enabled,selfServiceOnly};const command=product?{...productInput,expectedVersion:product.version}:pendingCreate??{...productInput,mutationId:crypto.randomUUID()};if(!product)setPendingCreate(command as ProductCreateCommand);try{await api(product?`/products/${product.id}`:'/products',{method:product?'PATCH':'POST',body:json(command)});onSaved()}catch(caught){if(!product&&isPermanentSyncConflict(caught))setPendingCreate(undefined);setError(apiErrorMessage(caught,language,t('requestFailed')))}};
  return <Modal title={`${product?t('edit'):t('add')} ${t('products')}`} onClose={onClose}><form className="stack" onSubmit={submit}><div className="translation-grid">{(['de','it','en'] as const).map(code=><Field key={code} label={`${t('name')} · ${code.toUpperCase()}`}><input value={name[code]} onChange={e=>setName({...name,[code]:e.target.value})} required={code==='de'} disabled={locked}/></Field>)}</div><div className="translation-grid">{(['de','it','en'] as const).map(code=><Field key={code} label={`${t('description')} · ${code.toUpperCase()}`}><input value={description[code]} onChange={e=>setDescription({...description,[code]:e.target.value})} disabled={locked}/></Field>)}</div><div className="form-grid"><Field label={`${t('price')} · EUR`}><input value={price} onChange={e=>setPrice(e.target.value)} inputMode="decimal" pattern="[0-9]+([.,][0-9]{1,2})?" required disabled={locked}/></Field><Field label={t('category')}><select value={categoryId} onChange={e=>setCategoryId(e.target.value)} required disabled={locked}>{categories.map(category=><option key={category.id} value={category.id}>{localized(category.name,language)}</option>)}</select></Field></div><label className="toggle"><input type="checkbox" checked={enabled} onChange={e=>setEnabled(e.target.checked)} disabled={locked}/><span/>{t('enabledForOrders')}</label><label className="toggle"><input type="checkbox" checked={selfServiceOnly} onChange={e=>setSelfServiceOnly(e.target.checked)} disabled={locked}/><span/>{t('selfService')}</label>{error&&<Notice kind="error">{error}</Notice>}<div className="form-actions">{onRemove&&<Button variant="danger" type="button" onClick={()=>void onRemove()}><Trash2/> {t('archive')}</Button>}<span className="grow"/><Button variant="ghost" type="button" onClick={onClose}>{t('cancel')}</Button><Button type="submit">{locked?t('retry'):t('save')}</Button></div></form></Modal>;
}

interface PendingDenial{hostId:string;requestId:string;requestName:string;mutationId:string}
const pendingDenialKey=(hostId:string)=>`skybar-pending-denial:${hostId}`;
function loadPendingDenial(hostId:string):PendingDenial|undefined{try{const raw=localStorage.getItem(pendingDenialKey(hostId));if(!raw)return;const pending=JSON.parse(raw) as PendingDenial;if(pending.hostId===hostId&&pending.requestId&&pending.mutationId)return pending}catch{/* Remove malformed recovery state below. */}localStorage.removeItem(pendingDenialKey(hostId));return}
function persistPendingDenial(hostId:string,pending:PendingDenial|undefined){if(pending)localStorage.setItem(pendingDenialKey(hostId),JSON.stringify(pending));else localStorage.removeItem(pendingDenialKey(hostId))}

export function RequestsPage(){
  const {t,language}=useI18n();const {host}=useHostContext();const client=useQueryClient();const requests=useQuery<{data:AccessRequest[]}>({queryKey:['requests'],queryFn:()=>list('/access-requests')});const guests=useQuery<{data:Guest[]}>({queryKey:['guests'],queryFn:()=>list('/guests')});const [approving,setApproving]=useState<AccessRequest|undefined>();const [pendingDenial,setPendingDenial]=useState<PendingDenial|undefined>(()=>loadPendingDenial(host.id));const [denialError,setDenialError]=useState('');
  const denyRequest=async(requestId:string,requestName:string)=>{const command=pendingDenial?.requestId===requestId?pendingDenial:{hostId:host.id,requestId,requestName,mutationId:crypto.randomUUID()};setPendingDenial(command);persistPendingDenial(host.id,command);setDenialError('');try{await api(`/access-requests/${requestId}/deny`,{method:'POST',body:json({mutationId:command.mutationId})});setPendingDenial(undefined);persistPendingDenial(host.id,undefined);await client.invalidateQueries({queryKey:['requests']})}catch(caught){if(isPermanentSyncConflict(caught)){setPendingDenial(undefined);persistPendingDenial(host.id,undefined)}setDenialError(apiErrorMessage(caught,language,t('requestFailed')))}};
  return <><PageHeader eyebrow={t('liveQueue')} title={t('requests')} actions={requests.data?.data.length?<span className="live-pill"><span/>{requests.data.data.length} {t('pending')}</span>:undefined}/>{pendingDenial&&<Card><Notice kind="error">{denialError||t('requestFailed')}</Notice><Button onClick={()=>void denyRequest(pendingDenial.requestId,pendingDenial.requestName)}>{t('retry')} · {pendingDenial.requestName}</Button></Card>}{denialError&&!pendingDenial&&<Notice kind="error">{denialError}</Notice>}<div className="request-grid">{requests.data?.data.map(request=><Card key={request.id} className="request-card"><div className="request-avatar"><UserRoundCheck/></div><div className="grow"><h2>{request.name}</h2><p><BedDouble/> {request.roomName}</p><span>{new Date(request.requestedAt).toLocaleTimeString(language)} · {request.language.toUpperCase()}</span></div><div className="request-actions"><Button onClick={()=>setApproving(request)}><Check/> {t('approve')}</Button><Button variant="ghost" disabled={Boolean(pendingDenial&&pendingDenial.requestId!==request.id)} onClick={()=>void denyRequest(request.id,request.name)}>{pendingDenial?.requestId===request.id?t('retry'):t('deny')}</Button></div></Card>)}</div>{!requests.data?.data.length&&!pendingDenial&&<Card><Empty>{t('empty')}</Empty></Card>}{approving&&<ApproveRequestModal request={approving} guests={guests.data?.data??[]} onClose={()=>setApproving(undefined)} onApproved={async()=>{setApproving(undefined);await client.invalidateQueries()}}/>}</>;
}

function ApproveRequestModal({request,guests,onClose,onApproved}:{request:AccessRequest;guests:Guest[];onClose:()=>void;onApproved:()=>void}){
  const {t,language}=useI18n();const matches=guests.filter(guest=>guest.roomId===request.roomId);const [guestId,setGuestId]=useState('new');const [expiresAt,setExpiresAt]=useState(()=>toLocalDateTimeInputValue(new Date(Date.now()+24*60*60*1000)));const [error,setError]=useState('');const [pendingCommand,setPendingCommand]=useState<{mutationId:string;guestId?:string;expiresAt:string}>();const submit=async(e:FormEvent)=>{e.preventDefault();const command=pendingCommand??{mutationId:crypto.randomUUID(),...(guestId==='new'?{}:{guestId}),expiresAt:new Date(expiresAt).toISOString()};setPendingCommand(command);try{await api(`/access-requests/${request.id}/approve`,{method:'POST',body:json(command)});onApproved()}catch(caught){if(isPermanentSyncConflict(caught))setPendingCommand(undefined);setError(apiErrorMessage(caught,language,t('requestFailed')))}};
  return <Modal title={`${t('approve')} · ${request.name}`} onClose={onClose}><form className="stack" onSubmit={submit}><Field label={t('linkGuest')}><select value={guestId} onChange={e=>setGuestId(e.target.value)} disabled={Boolean(pendingCommand)}><option value="new">{t('createGuest')} · {request.name} · {request.roomName}</option>{matches.map(guest=><option key={guest.id} value={guest.id}>{t('linkTo')} {guest.name}</option>)}</select></Field><Field label={t('accessExpires')}><input type="datetime-local" value={expiresAt} onChange={e=>setExpiresAt(e.target.value)} required disabled={Boolean(pendingCommand)}/></Field>{error&&<Notice kind="error">{error}</Notice>}<Button type="submit"><Check/> {pendingCommand?t('retry'):t('approve')}</Button></form></Modal>;
}

interface DeviceSession{id:string;userAgent:string;createdAt:string;lastSeenAt:string;expiresAt:string;current:boolean}
interface ManagedHost{id:string;name:string;email:string;role:'admin'|'staff';language:Language;active:boolean;version:number}
export function AccountPage(){
  const {t,setLanguage}=useI18n();const {host}=useHostContext();const client=useQueryClient();const [,navigate]=useLocation();const sessions=useQuery<{data:DeviceSession[]}>({queryKey:['sessions'],queryFn:()=>list('/account/sessions')});const hosts=useQuery<{data:ManagedHost[]}>({queryKey:['hosts'],queryFn:()=>list('/hosts'),enabled:host.role==='admin'});const [name,setName]=useState(host.name);const [language,setLang]=useState<Language>(host.language);const [currentPassword,setCurrentPassword]=useState('');const [newPassword,setNewPassword]=useState('');const [message,setMessage]=useState<{kind:'success'|'error';text:string}|null>(null);const [addHost,setAddHost]=useState(false);
  const save=async(e:FormEvent)=>{e.preventDefault();setMessage(null);try{await api('/account',{method:'PATCH',body:json({name,language,currentPassword:currentPassword||undefined,newPassword:newPassword||undefined})});setLanguage(language);setCurrentPassword('');setNewPassword('');setMessage({kind:'success',text:t('accountUpdated')});await client.invalidateQueries({queryKey:['me']})}catch(caught){setMessage({kind:'error',text:apiErrorMessage(caught,language,t('requestFailed'))})}};
  const revokeSession=async(session:DeviceSession)=>{await api(`/account/sessions/${session.id}`,{method:'DELETE'});if(session.current){client.clear();navigate('/login',{replace:true});globalThis.location.assign('/login');return}await client.invalidateQueries({queryKey:['sessions']})};
  const toggleHost=async(item:ManagedHost)=>{setMessage(null);try{await api(`/hosts/${item.id}`,{method:'PATCH',body:json({active:!item.active,expectedVersion:item.version})})}catch(caught){setMessage({kind:'error',text:apiErrorMessage(caught,language,t('requestFailed'))})}finally{await client.invalidateQueries({queryKey:['hosts']})}};
  return <><PageHeader eyebrow={host.email} title={t('account')}/>{message&&<Notice kind={message.kind}>{message.text}</Notice>}<div className="two-column"><Card><h2>{t('profileCredentials')}</h2><form className="stack" onSubmit={save}><Field label={t('name')}><input value={name} onChange={e=>setName(e.target.value)} required/></Field><Field label={t('language')}><select value={language} onChange={e=>setLang(e.target.value as Language)}><option value="de">Deutsch</option><option value="it">Italiano</option><option value="en">English</option></select></Field><hr/><Field label={t('currentPassword')}><input type="password" autoComplete="current-password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)}/></Field><Field label={t('newPassword')} hint={t('passwordHint')}><input type="password" autoComplete="new-password" minLength={12} value={newPassword} onChange={e=>setNewPassword(e.target.value)}/></Field><Button type="submit">{t('save')}</Button></form></Card><Card><h2>{t('loggedInDevices')}</h2><div className="device-list">{sessions.data?.data.map(session=><div key={session.id}><div className="device-icon">▣</div><div className="grow"><strong>{session.current?t('thisDevice'):session.userAgent.slice(0,55)}</strong><span>{t('lastActive')} {new Date(session.lastSeenAt).toLocaleString(language)}</span></div><Button variant="ghost" onClick={()=>void revokeSession(session)}>{session.current?t('logout'):t('revoke')}</Button></div>)}</div></Card></div>{host.role==='admin'&&<><div className="section-heading"><h2>{t('hostAccounts')}</h2><Button onClick={()=>setAddHost(true)}><UserPlus/> {t('add')}</Button></div><Card><div className="table-list">{hosts.data?.data.map(item=><div className="table-row" key={item.id}><div className="avatar">{item.name.charAt(0)}</div><div className="grow"><strong>{item.name}</strong><span>{item.email}</span></div><span className="payment-tag">{t(item.role)}</span><span className={`status-dot ${item.active?'enabled':''}`}>{item.active?t('active'):t('inactive')}</span>{item.id!==host.id&&<Button variant="ghost" onClick={()=>void toggleHost(item)}>{item.active?t('disable'):t('enable')}</Button>}</div>)}</div></Card></>}{addHost&&<NewHostModal onClose={()=>setAddHost(false)} onCreated={async()=>{setAddHost(false);await client.invalidateQueries({queryKey:['hosts']})}}/>}</>;
}

function NewHostModal({onClose,onCreated}:{onClose:()=>void;onCreated:()=>void}){const {t,language}=useI18n();const [name,setName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [role,setRole]=useState<'admin'|'staff'>('staff');const [error,setError]=useState('');const [pendingCommand,setPendingCommand]=useState<{mutationId:string;name:string;email:string;password:string;role:'admin'|'staff';language:'de'}>();const submit=async(e:FormEvent)=>{e.preventDefault();const command=pendingCommand??{mutationId:crypto.randomUUID(),name,email,password,role,language:'de'};setPendingCommand(command);try{await api('/hosts',{method:'POST',body:json(command)});onCreated()}catch(caught){if(isPermanentSyncConflict(caught))setPendingCommand(undefined);setError(apiErrorMessage(caught,language,t('requestFailed')))}};return <Modal title={t('addHost')} onClose={onClose}><form className="stack" onSubmit={submit}><Field label={t('name')}><input value={name} onChange={e=>setName(e.target.value)} required disabled={Boolean(pendingCommand)}/></Field><Field label={t('email')}><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required disabled={Boolean(pendingCommand)}/></Field><Field label={t('temporaryPassword')}><input type="password" minLength={12} value={password} onChange={e=>setPassword(e.target.value)} required disabled={Boolean(pendingCommand)}/></Field><Field label={t('role')}><select value={role} onChange={e=>setRole(e.target.value as 'admin'|'staff')} disabled={Boolean(pendingCommand)}><option value="staff">{t('staff')}</option><option value="admin">{t('admin')}</option></select></Field>{error&&<Notice kind="error">{error}</Notice>}<Button type="submit">{pendingCommand?t('retry'):t('createAccount')}</Button></form></Modal>}

export function SettingsPage(){
  const {t,language:uiLanguage}=useI18n();const {host}=useHostContext();const client=useQueryClient();const venue=useQuery<Venue>({queryKey:['venue'],queryFn:()=>api('/venue')});const rooms=useQuery<{data:Room[]}>({queryKey:['rooms'],queryFn:()=>list('/rooms')});const [name,setName]=useState('');const [timezone,setTimezone]=useState('Europe/Berlin');const [language,setLanguage]=useState<Language>('de');const [initialized,setInitialized]=useState(false);const [saved,setSaved]=useState(false);const [error,setError]=useState('');const configuredName=name;const base=location.origin;
  useEffect(()=>{if(!venue.data)return;setName(venue.data.name);setTimezone(venue.data.timezone);setLanguage(venue.data.defaultLanguage);setInitialized(true)},[venue.data?.name,venue.data?.timezone,venue.data?.defaultLanguage]);
  const submit=async(e:FormEvent)=>{e.preventDefault();setSaved(false);setError('');try{const updated=await api<Venue>('/venue',{method:'PUT',body:json({name:configuredName,timezone:timezone||venue.data?.timezone||'Europe/Berlin',language,expectedVersion:venue.data!.version})});client.setQueryData(['venue'],updated);client.setQueryData<{host:Host;venue:Venue}>(['me'],current=>current?{...current,venue:updated}:current);setSaved(true)}catch(caught){setError(apiErrorMessage(caught,uiLanguage,t('requestFailed')))}};
  if(host.role!=='admin')return <Card><Notice kind="error">{t('permissionRequired')}</Notice></Card>;
  if(!initialized)return <div className="splash">{t('loading')}</div>;
  return <><PageHeader eyebrow={`Sky Bar · ${t('configuration')}`} title={t('settings')}/>{saved&&<Notice>{t('venueSaved')}</Notice>}{error&&<Notice kind="error">{error}</Notice>}<div className="two-column"><Card><h2>{t('venueIdentity')}</h2><p className="muted">{t('venueIdentityHelp')}</p><form className="stack" onSubmit={submit}><Field label={t('venueName')}><input value={name} onChange={e=>setName(e.target.value)} required maxLength={120} placeholder={t('venueName')}/></Field><Field label={t('defaultLanguage')}><select value={language} onChange={e=>setLanguage(e.target.value as Language)}><option value="de">Deutsch</option><option value="it">Italiano</option><option value="en">English</option></select></Field><Field label={t('timezone')}><input value={timezone} onChange={e=>setTimezone(e.target.value)} required/></Field><Button type="submit">{t('save')}</Button></form></Card><Card className="qr-card"><h2>{t('venueGuestAccess')}</h2><QRCodeSVG className="qr-code" value={`${base}/guest/request`} size={190} bgColor="#ffffff" fgColor="#07101b" level="M" marginSize={2}/><code>{base}/guest/request</code><Button variant="secondary" onClick={()=>window.print()}><Printer/> {t('print')}</Button></Card></div><div className="section-heading"><h2>{t('roomQrCodes')}</h2></div><div className="qr-grid">{rooms.data?.data.map(room=><Card className="qr-card" key={room.id}><h3>{room.name}</h3><QRCodeSVG className="qr-code" value={`${base}/guest/request?room=${room.id}`} size={150} bgColor="#ffffff" fgColor="#07101b" level="M" marginSize={2}/><small>{t('roomPreselected')}</small></Card>)}</div></>;
}
